"use client";

import React from "react";
import { useDictionary } from "@/hooks/useDictionary";

export default function Home() {
  const {
    loading,
    wordsCount,
    searchQuery,
    setSearchQuery,
    seciliLehce,
    setSeciliLehce,
    seciliDosya,
    setSeciliDosya,
    gununKelimesi,
    filtrelenmisSonuclar,
    aktifSozlukler,
  } = useDictionary();

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif", maxWidth: "800px", margin: "0 auto", color: "#333" }}>
      {/* Üst Başlık */}
      <header style={{ borderBottom: "2px solid #e2e8f0", paddingBottom: "15px", marginBottom: "20px" }}>
        <h1 style={{ margin: "0 0 8px 0", color: "#1e293b", fontSize: "28px" }}>📖 Çerkesçe Sözlük</h1>
        <p style={{ margin: 0, color: "#64748b", fontSize: "14px" }}>
          {loading ? "Veritabanı hazırlanıyor..." : `Toplam ${wordsCount} kelime yüklendi.`}
        </p>
      </header>

      {/* Günün Kelimesi */}
      {gununKelimesi && (
        <div style={{ background: "#f0f9ff", padding: "15px", borderRadius: "8px", marginBottom: "20px", border: "1px solid #bae6fd" }}>
          <strong style={{ color: "#0369a1", fontSize: "12px", textTransform: "uppercase" }}>Günün Kelimesi</strong>
          <div style={{ fontSize: "20px", fontWeight: "bold", margin: "4px 0", color: "#0c4a6e" }}>{gununKelimesi.kelime}</div>
          <div style={{ color: "#0369a1", fontSize: "14px" }}>{gununKelimesi.tanim}</div>
        </div>
      )}

      {/* Arama ve Filtre Kartı */}
      <div style={{ background: "#f8fafc", padding: "15px", borderRadius: "8px", border: "1px solid #e2e8f0", marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Kelime veya anlam ara..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={{ width: "100%", padding: "12px", fontSize: "16px", border: "1px solid #cbd5e1", borderRadius: "6px", boxSizing: "border-box", marginBottom: "12px" }}
        />

        <div style={{ display: "flex", gap: "8px", flexWrap: "wrap", alignItems: "center" }}>
          <button
            onClick={() => setSeciliLehce("TUMU")}
            style={{ padding: "6px 12px", background: seciliLehce === "TUMU" ? "#2563eb" : "#e2e8f0", color: seciliLehce === "TUMU" ? "#fff" : "#334155", border: "none", borderRadius: "4px", cursor: "pointer", fontWeight: 500 }}
          >
            Tümü
          </button>
          <button
            onClick={() => setSeciliLehce("BATI")}
            style={{ padding: "6px 12px", background: seciliLehce === "BATI" ? "#2563eb" : "#e2e8f0", color: seciliLehce === "BATI" ? "#fff" : "#334155", border: "none", borderRadius: "4px", cursor: "pointer", fontWeight: 500 }}
          >
            Batı (Adıgece)
          </button>
          <button
            onClick={() => setSeciliLehce("DOGU")}
            style={{ padding: "6px 12px", background: seciliLehce === "DOGU" ? "#2563eb" : "#e2e8f0", color: seciliLehce === "DOGU" ? "#fff" : "#334155", border: "none", borderRadius: "4px", cursor: "pointer", fontWeight: 500 }}
          >
            Doğu (Kabardeyce)
          </button>

          <select
            value={seciliDosya}
            onChange={(e) => setSeciliDosya(e.target.value)}
            style={{ padding: "6px 12px", borderRadius: "4px", border: "1px solid #cbd5e1", marginLeft: "auto", background: "#fff" }}
          >
            <option value="TUMU">Tüm Sözlükler ({aktifSozlukler.length})</option>
            {aktifSozlukler.map((s) => (
              <option key={s.file} value={s.file}>
                {s.title}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Liste Ekranı */}
      {loading ? (
        <div style={{ textAlign: "center", padding: "40px", color: "#64748b" }}>
          📖 Sözlükler yükleniyor, lütfen bekleyin...
        </div>
      ) : (
        <ul style={{ listStyle: "none", padding: 0, margin: 0, border: "1px solid #e2e8f0", borderRadius: "8px", background: "#fff" }}>
          {filtrelenmisSonuclar.length === 0 ? (
            <li style={{ padding: "20px", textAlign: "center", color: "#94a3b8" }}>Sonuç bulunamadı.</li>
          ) : (
            filtrelenmisSonuclar.slice(0, 50).map((item, index) => (
              <li key={index} style={{ padding: "12px 16px", borderBottom: "1px solid #f1f5f9" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                  <strong style={{ fontSize: "16px", color: "#0f172a" }}>{item.kelime}</strong>
                  <span style={{ fontSize: "11px", color: "#64748b", background: "#f1f5f9", padding: "2px 6px", borderRadius: "4px" }}>
                    {item.kaynak_sozluk || item.file}
                  </span>
                </div>
                <p style={{ margin: "4px 0 0 0", color: "#334155", fontSize: "14px", whiteSpace: "pre-line" }}>{item.tanim}</p>
              </li>
            ))
          )}
        </ul>
      )}
    </div>
  );
}